//go:build ((linux && amd64) || ((linux || darwin) && arm64)) && !tinygo && !wago_guardpage

package wago

import "testing"

// Exception records were a fixed reservation of four try_table levels and four
// rooted exception values per function. Frames are now sized from each
// function's own nesting depth and catch_ref count.
func TestExceptionFramesSizedPerFunction(t *testing.T) {
	for _, tc := range []struct {
		module string
		export string
		want   int32
	}{
		{ehDeepWasm, "deep", 151}, // six nested try_tables
		{ehDeepWasm, "refs", 45},  // ten catch_ref roots, rethrown later
		{ehDeepWasm, "rec", 3000}, // 2,000 recursive EH frames
		{ehFuncrefPayloadWasm, "f", 28},
	} {
		if got := invokeI32(t, admissionModule(t, tc.module), tc.export); got != tc.want {
			t.Fatalf("%s = %d, want %d", tc.export, got, tc.want)
		}
	}
}

// ehDeepWasm encodes:
//
//	(module
//	  (tag $t (param i32))
//	  (func (export "deep") (result i32)
//	    (block $out (result i32)
//	      (try_table (catch $t $out) (block $h0 (result i32) (try_table (catch $t $h0) (block $h1 (result i32) (try_table (catch $t $h1) (block $h2 (result i32) (try_table (catch $t $h2) (block $h3 (result i32) (try_table (catch $t $h3) (block $h4 (result i32) (try_table (catch $t $h4) (block $h5 (result i32) (try_table (catch $t $h5) (throw $t (i32.const 1))) (unreachable)) (i32.add (i32.const 50)) (throw $t)) (unreachable)) (i32.add (i32.const 40)) (throw $t)) (unreachable)) (i32.add (i32.const 30)) (throw $t)) (unreachable)) (i32.add (i32.const 20)) (throw $t)) (unreachable)) (i32.add (i32.const 10)) (throw $t)) (unreachable)) (i32.add (i32.const 0)) (throw $t))
//	      (i32.const -1)))
//	  (func (export "refs") (result i32)  (local exnref) (local exnref) (local exnref) (local exnref) (local exnref) (local exnref) (local exnref) (local exnref) (local exnref) (local exnref)
//
//	    (block $r0 (result i32 exnref)
//	      (try_table (catch_ref $t $r0) (throw $t (i32.const 0)))
//	      (unreachable))
//	    (local.set 0) (drop)
//	    (block $r1 (result i32 exnref)
//	      (try_table (catch_ref $t $r1) (throw $t (i32.const 1)))
//	      (unreachable))
//	    (local.set 1) (drop)
//	    (block $r2 (result i32 exnref)
//	      (try_table (catch_ref $t $r2) (throw $t (i32.const 2)))
//	      (unreachable))
//	    (local.set 2) (drop)
//	    (block $r3 (result i32 exnref)
//	      (try_table (catch_ref $t $r3) (throw $t (i32.const 3)))
//	      (unreachable))
//	    (local.set 3) (drop)
//	    (block $r4 (result i32 exnref)
//	      (try_table (catch_ref $t $r4) (throw $t (i32.const 4)))
//	      (unreachable))
//	    (local.set 4) (drop)
//	    (block $r5 (result i32 exnref)
//	      (try_table (catch_ref $t $r5) (throw $t (i32.const 5)))
//	      (unreachable))
//	    (local.set 5) (drop)
//	    (block $r6 (result i32 exnref)
//	      (try_table (catch_ref $t $r6) (throw $t (i32.const 6)))
//	      (unreachable))
//	    (local.set 6) (drop)
//	    (block $r7 (result i32 exnref)
//	      (try_table (catch_ref $t $r7) (throw $t (i32.const 7)))
//	      (unreachable))
//	    (local.set 7) (drop)
//	    (block $r8 (result i32 exnref)
//	      (try_table (catch_ref $t $r8) (throw $t (i32.const 8)))
//	      (unreachable))
//	    (local.set 8) (drop)
//	    (block $r9 (result i32 exnref)
//	      (try_table (catch_ref $t $r9) (throw $t (i32.const 9)))
//	      (unreachable))
//	    (local.set 9) (drop)
//	    (i32.const 0)
//
//	    (block $c0 (result i32)
//	      (try_table (catch $t $c0) (throw_ref (local.get 0)))
//	      (unreachable))
//	    (i32.add)
//	    (block $c1 (result i32)
//	      (try_table (catch $t $c1) (throw_ref (local.get 1)))
//	      (unreachable))
//	    (i32.add)
//	    (block $c2 (result i32)
//	      (try_table (catch $t $c2) (throw_ref (local.get 2)))
//	      (unreachable))
//	    (i32.add)
//	    (block $c3 (result i32)
//	      (try_table (catch $t $c3) (throw_ref (local.get 3)))
//	      (unreachable))
//	    (i32.add)
//	    (block $c4 (result i32)
//	      (try_table (catch $t $c4) (throw_ref (local.get 4)))
//	      (unreachable))
//	    (i32.add)
//	    (block $c5 (result i32)
//	      (try_table (catch $t $c5) (throw_ref (local.get 5)))
//	      (unreachable))
//	    (i32.add)
//	    (block $c6 (result i32)
//	      (try_table (catch $t $c6) (throw_ref (local.get 6)))
//	      (unreachable))
//	    (i32.add)
//	    (block $c7 (result i32)
//	      (try_table (catch $t $c7) (throw_ref (local.get 7)))
//	      (unreachable))
//	    (i32.add)
//	    (block $c8 (result i32)
//	      (try_table (catch $t $c8) (throw_ref (local.get 8)))
//	      (unreachable))
//	    (i32.add)
//	    (block $c9 (result i32)
//	      (try_table (catch $t $c9) (throw_ref (local.get 9)))
//	      (unreachable))
//	    (i32.add))
//	  (func $rec (param i32) (result i32)
//	    (block $h (result i32)
//	      (try_table (catch $t $h)
//	        (if (i32.eqz (local.get 0)) (then (throw $t (i32.const 0))))
//	        (return (i32.add (call $rec (i32.sub (local.get 0) (i32.const 1))) (i32.const 1))))
//	      (unreachable))
//	    (i32.const 1000) (i32.add))
//	  (func (export "rec") (result i32) (call $rec (i32.const 2000)))
//	)
const ehDeepWasm = ""

// ehFuncrefPayloadWasm encodes:
//
//	(module
//	  (type $f (func (result i32)))
//	  (tag $t (param (ref $f)))
//	  (func $k0 (type $f) (i32.const 1))
//	  (func $k1 (type $f) (i32.const 2))
//	  (func $k2 (type $f) (i32.const 3))
//	  (func $k3 (type $f) (i32.const 4))
